begin;
select no_plan();
create function pg_temp.ai_id(n integer) returns uuid language sql immutable as $$select ('aa030000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,instance_id,aud,role,email) select pg_temp.ai_id(n),'00000000-0000-0000-0000-000000000000','authenticated','authenticated','ai-auth-'||n||'@test.invalid' from generate_series(1,8) n;
insert into auth.users(id,instance_id,aud,role,email) values(pg_temp.ai_id(10),'00000000-0000-0000-0000-000000000000','authenticated','authenticated','ai-missing-profile@test.invalid');
insert into public.profiles(id,role,name) select pg_temp.ai_id(n),case n when 1 then 'admin' when 2 then 'staff' when 3 then 'teacher' when 4 then 'assistant' when 5 then 'viewer' else 'staff' end,'AI fixture '||n from generate_series(1,8) n on conflict(id) do update set role=excluded.role;
update auth.users set deleted_at=clock_timestamp() where id=pg_temp.ai_id(6);
update auth.users set banned_until=clock_timestamp()+interval '1 day' where id=pg_temp.ai_id(7);
create temp table evidence(k text primary key,v jsonb);
grant all on evidence to authenticated;
create function pg_temp.ai_create(n integer) returns jsonb language sql as $$select public.ai_agent_user_api_v1('create',jsonb_build_object('title','fixture','body','synthetic','notifyOnDone',false,'idempotencyKey',pg_temp.ai_id(100+n)))$$;
select set_config('request.jwt.claim.sub',pg_temp.ai_id(2)::text,true);
set local role authenticated;
insert into evidence values('staff',pg_temp.ai_create(2));
select is(public.ai_agent_user_api_v1('list','{}')->>'total','1','staff owns only');
select is(public.ai_agent_user_api_v1('get',jsonb_build_object('id',(select v->>'id' from evidence where k='staff')))->>'requesterId',pg_temp.ai_id(2)::text,'staff own get');
select is(pg_temp.ai_create(2)->>'id',(select v->>'id' from evidence where k='staff'),'idempotent create replays original request');
select is(jsonb_typeof(pg_temp.ai_create(2)->'version'),'string','bigint request version is precision-safe decimal string');
select throws_ok($q$select public.ai_agent_user_api_v1('create',jsonb_build_object('title','changed','body','synthetic','notifyOnDone',false,'idempotencyKey',pg_temp.ai_id(102)))$q$,'23514','ai_agent_idempotency_conflict','business idempotency conflict has exact 23514, never 40001');
select throws_ok($q$select public.ai_agent_user_api_v1('list','{"scope":null}')$q$,'22023','ai_agent_invalid','null query fields denied');
select throws_ok($q$select public.ai_agent_user_api_v1('get','{"id":"bad"}')$q$,'22023','ai_agent_invalid','malformed UUID denied');
select throws_ok($q$select public.ai_agent_user_api_v1('create',jsonb_build_object('title','x','body','x','notifyOnDone',false,'requester',pg_temp.ai_id(1),'idempotencyKey',pg_temp.ai_id(199)))$q$,'22023','ai_agent_invalid','caller-selected actor rejected');
select throws_ok($q$select dashboard_private.ai_agent_lock_user_v1(false)$q$,'42501',null,'private decisive lock helper cannot be called by authenticated clients');
select throws_ok($q$select public.ai_agent_user_api_v1('list','{"scope":"all"}')$q$,'42501','ai_agent_forbidden','staff cannot read all');
reset role;
select set_config('request.jwt.claim.sub',pg_temp.ai_id(3)::text,true);
set local role authenticated;
insert into evidence values('teacher',pg_temp.ai_create(3));
select is(public.ai_agent_user_api_v1('list','{}')->>'total','1','teacher owns only');
select is(public.ai_agent_user_api_v1('get',jsonb_build_object('id',(select v->>'id' from evidence where k='teacher')))->>'requesterId',pg_temp.ai_id(3)::text,'teacher own get');
select throws_ok($q$select public.ai_agent_user_api_v1('get',jsonb_build_object('id',(select v->>'id' from evidence where k='staff')))$q$,'P0002','ai_agent_not_found','other ID has no content');
reset role;
select set_config('request.jwt.claim.sub',pg_temp.ai_id(4)::text,true);
set local role authenticated;
select throws_ok($q$select pg_temp.ai_create(4)$q$,'42501','ai_agent_forbidden','assistant cannot create AI requests');
select throws_ok($q$select public.ai_agent_user_api_v1('list','{}')$q$,'42501','ai_agent_forbidden','assistant cannot list AI requests');
select throws_ok($q$select public.ai_agent_user_api_v1('get',jsonb_build_object('id',(select v->>'id' from evidence where k='staff')))$q$,'42501','ai_agent_forbidden','assistant cannot read an AI ID');
reset role;
select is((select count(*) from dashboard_private.ai_agent_requests where requester_id=pg_temp.ai_id(4)),0::bigint,'assistant denial creates zero request');
select set_config('request.jwt.claim.sub',pg_temp.ai_id(8)::text,true);
set local role authenticated;
insert into evidence values('second_staff',pg_temp.ai_create(8));
select is(public.ai_agent_user_api_v1('list','{}')->>'total','1','second staff owns only');
select is(public.ai_agent_user_api_v1('get',jsonb_build_object('id',(select v->>'id' from evidence where k='second_staff')))->>'requesterId',pg_temp.ai_id(8)::text,'second staff own get');
reset role;
select set_config('request.jwt.claim.sub',pg_temp.ai_id(1)::text,true);
set local role authenticated;
select is(public.ai_agent_user_api_v1('list','{"scope":"all"}')->>'total','3','admin reads all');
select is(public.ai_agent_user_api_v1('get',jsonb_build_object('id',(select v->>'id' from evidence where k='teacher')))->>'requesterId',pg_temp.ai_id(3)::text,'admin reads another requester');
reset role;
select set_config('request.jwt.claim.sub',pg_temp.ai_id(5)::text,true);
set local role authenticated;
select throws_ok($q$select public.ai_agent_user_api_v1('list','{}')$q$,'42501','ai_agent_forbidden','viewer rejected');
reset role;
select set_config('request.jwt.claim.sub',pg_temp.ai_id(6)::text,true);
set local role authenticated;
select throws_ok($q$select public.ai_agent_user_api_v1('list','{}')$q$,'42501','ai_agent_forbidden','deleted rejected');
reset role;
select set_config('request.jwt.claim.sub',pg_temp.ai_id(7)::text,true);
set local role authenticated;
select throws_ok($q$select public.ai_agent_user_api_v1('list','{}')$q$,'42501','ai_agent_forbidden','banned rejected');
reset role;
select set_config('request.jwt.claim.sub',pg_temp.ai_id(10)::text,true);
set local role authenticated;
select throws_ok($q$select public.ai_agent_user_api_v1('list','{}')$q$,'42501','ai_agent_forbidden','missing profile rejected');
reset role;
set local role anon;
select throws_ok($q$select * from dashboard_private.ai_agent_requests$q$,'42501',null,'anon cannot access private table');
select throws_ok($q$select public.ai_agent_user_api_v1('list','{}')$q$,'42501',null,'anon cannot execute staff gateway');
reset role;
set local role service_role;
select throws_ok($q$select * from dashboard_private.ai_agent_requests$q$,'42501',null,'service_role cannot access private table');
select throws_ok($q$select public.ai_agent_user_api_v1('list','{}')$q$,'42501',null,'service_role cannot impersonate user RPC');
reset role;
select ok((select bool_and(relrowsecurity) from pg_class where oid in('dashboard_private.ai_agent_requests'::regclass,'dashboard_private.ai_agent_request_messages'::regclass,'dashboard_private.ai_agent_request_events'::regclass,'dashboard_private.ai_agent_request_claims'::regclass,'dashboard_private.ai_agent_request_receipts'::regclass)),'all new private request stores have RLS');
select ok((select count(*)=3 from dashboard_private.ai_agent_request_events where kind='created'),'creation records immutable audit');
select throws_ok($q$update dashboard_private.ai_agent_request_events set kind='changed'$q$,'55000','ai_agent_immutable','audit mutation rejected with exact SQLSTATE');
select throws_ok($q$delete from dashboard_private.ai_agent_request_receipts$q$,'55000','ai_agent_immutable','receipt deletion rejected with exact SQLSTATE');
select ok(not exists(select 1 from unnest(array['anon','authenticated','service_role']) role_name cross join unnest(array['ai_agent_requests','ai_agent_request_messages','ai_agent_request_events','ai_agent_request_claims','ai_agent_request_receipts']) table_name where has_table_privilege(role_name,'dashboard_private.'||table_name,'SELECT,INSERT,UPDATE,DELETE')),'every private request table denies direct access');
select set_config('request.jwt.claim.sub',pg_temp.ai_id(2)::text,true);
set local role authenticated;
select lives_ok($q$select pg_temp.ai_create(n) from generate_series(10,18) n$q$,'remaining nine creates fit hourly budget');
select throws_ok($q$select pg_temp.ai_create(19)$q$,'54000','ai_agent_rate_limited','eleventh create blocked atomically');
select is(pg_temp.ai_create(2)->>'id',(select v->>'id' from evidence where k='staff'),'replay consumes no hourly budget');
reset role;
update public.profiles set role='viewer' where id=pg_temp.ai_id(2);
set local role authenticated;
select throws_ok($q$select pg_temp.ai_create(2)$q$,'42501','ai_agent_forbidden','current authorization rechecked before replay');
reset role;
insert into auth.users(id,instance_id,aud,role,email) values(pg_temp.ai_id(9),'00000000-0000-0000-0000-000000000000','authenticated','authenticated','ai-optin-owner@test.invalid');
insert into public.profiles(id,role,name) values(pg_temp.ai_id(9),'staff','synthetic opt-in owner') on conflict(id) do update set role=excluded.role;
insert into dashboard_private.chat_user_space_permissions(user_id,space_keys,configured_by) values(pg_temp.ai_id(9),array['space_1','space_2','space_3'],pg_temp.ai_id(1));
create function pg_temp.opt_create(k integer,extra jsonb default '{}') returns jsonb language sql as $$select public.ai_agent_user_api_v1('create',jsonb_build_object('title','opt-in fixture','body','synthetic','idempotencyKey',pg_temp.ai_id(k))||extra)$$;
insert into evidence values('before_optin',jsonb_build_object('outbox',(select count(*) from dashboard_private.chat_delivery_outbox),'events',(select count(*) from dashboard_private.notification_events),'deliveries',(select count(*) from dashboard_private.notification_deliveries)));
select is((select issuance_enabled from dashboard_private.ai_agent_chat_support where singleton),false,'new credential issuance starts disabled independently of request creation');
select set_config('request.jwt.claim.sub',pg_temp.ai_id(9)::text,true);
set local role authenticated;
select ok((select count(*)=7 and bool_and(x->'configured'='false'::jsonb and x->'selectable'='false'::jsonb) from jsonb_array_elements(public.ai_agent_space_policy_api_v1('catalog','{}')->'items')x),'actual default disabled catalog exposes seven unconfigured unselectable slots');
select throws_ok($q$select pg_temp.opt_create(900,'{"notifyOnDone":true,"notificationSpace":"space_1"}')$q$,'42501','ai_agent_space_forbidden','public ON create is denied against default disabled catalog despite own allowed policy');
reset role;
select is(jsonb_build_object('requests',(select count(*) from dashboard_private.ai_agent_requests where requester_id=pg_temp.ai_id(9)),'receipts',(select count(*) from dashboard_private.ai_agent_request_receipts where principal_kind='user' and principal_id=pg_temp.ai_id(9) and operation='create'),'events',(select count(*) from dashboard_private.ai_agent_request_events where requester_id=pg_temp.ai_id(9))),jsonb_build_object('requests',0,'receipts',0,'events',0),'default disabled public ON denial creates zero request receipt and audit rows');
set local role authenticated;
insert into evidence values('default_off',pg_temp.opt_create(901));
reset role;
-- OFF succeeded against the default disabled catalog. Activate only fixture slots
-- inside this rolled-back test; the independent issuance flag remains false.
update dashboard_private.chat_space_configuration set configured=true,resource_name='spaces/OPTIN_'||space_key,public_origin='https://dashboard.test.invalid' where space_key in('space_1','space_2','space_4');
set local role authenticated;
select is((select v->'notifyOnDone' from evidence where k='default_off'),'false'::jsonb,'omitted consent defaults OFF');
select is((select v->'notificationSpace' from evidence where k='default_off'),'null'::jsonb,'default OFF has null notification slot');
select is(pg_temp.opt_create(901,'{"notifyOnDone":false}')->>'id',(select v->>'id' from evidence where k='default_off'),'explicit false and omitted consent share canonical OFF fingerprint');
insert into evidence values('optin_on',pg_temp.opt_create(902,'{"notifyOnDone":true,"notificationSpace":"space_1"}'));
select is((select v->'notifyOnDone' from evidence where k='optin_on'),'true'::jsonb,'ordinary requester can opt into own configured allowed slot');
select is((select v->>'notificationSpace' from evidence where k='optin_on'),'space_1','true create persists exact slot');
select is((select v->>'requesterId' from evidence where k='optin_on'),pg_temp.ai_id(9)::text,'notification create binds auth.uid requester');
select is((select v->>'status' from evidence where k='optin_on'),'pending','opt-in preserves initial pending state');
select is((select v->>'version' from evidence where k='optin_on'),'1','opt-in preserves initial version');
select is(pg_temp.opt_create(902,'{"notifyOnDone":true,"notificationSpace":"space_1"}'),(select v from evidence where k='optin_on'),'same consent and slot replay exact receipt');
select throws_ok($q$select pg_temp.opt_create(902,'{"notifyOnDone":false}')$q$,'23514','ai_agent_idempotency_conflict','changing ON to OFF conflicts with stored create fingerprint');
select throws_ok($q$select pg_temp.opt_create(902,'{"notifyOnDone":true,"notificationSpace":"space_2"}')$q$,'23514','ai_agent_idempotency_conflict','changing to another authorized slot conflicts with stored fingerprint');
select throws_ok($q$select pg_temp.opt_create(901,'{"notifyOnDone":true,"notificationSpace":"space_1"}')$q$,'23514','ai_agent_idempotency_conflict','changing OFF to ON conflicts with stored create fingerprint');
select throws_ok($q$select pg_temp.opt_create(903,'{"notifyOnDone":true}')$q$,'22023','ai_agent_invalid','ON requires a slot');
select throws_ok($q$select pg_temp.opt_create(903,'{"notifyOnDone":true,"notificationSpace":null}')$q$,'22023','ai_agent_invalid','ON rejects null slot');
select throws_ok($q$select pg_temp.opt_create(903,'{"notifyOnDone":true,"notificationSpace":1}')$q$,'22023','ai_agent_invalid','ON rejects nonstring slot');
select throws_ok($q$select pg_temp.opt_create(903,'{"notifyOnDone":true,"notificationSpace":"space_8"}')$q$,'22023','ai_agent_invalid','ON rejects invalid slot key');
select throws_ok($q$select pg_temp.opt_create(903,'{"notifyOnDone":"true","notificationSpace":"space_1"}')$q$,'22023','ai_agent_invalid','consent remains strictly boolean');
select throws_ok($q$select pg_temp.opt_create(903,'{"notifyOnDone":false,"notificationSpace":"space_1"}')$q$,'42501','ai_agent_space_forbidden','OFF retains prior supplied-space denial contract');
select throws_ok($q$select pg_temp.opt_create(903,'{"notifyOnDone":true,"notificationSpace":"space_3"}')$q$,'42501','ai_agent_space_forbidden','allowed but unconfigured slot denied');
select throws_ok($q$select pg_temp.opt_create(903,'{"notifyOnDone":true,"notificationSpace":"space_4"}')$q$,'42501','ai_agent_space_forbidden','configured but unallowed slot denied');
reset role;
select is((select payload_hash from dashboard_private.ai_agent_request_receipts where principal_kind='user' and principal_id=pg_temp.ai_id(9) and operation='create' and idempotency_key=pg_temp.ai_id(901)),encode(sha256(convert_to(jsonb_build_object('title','opt-in fixture','body','synthetic','notifyOnDone',false)::text,'UTF8')),'hex'),'OFF fingerprint stays byte-compatible with accepted six-chain receipts');
select is((select notify_on_done from dashboard_private.ai_agent_requests where id=(select (v->>'id')::uuid from evidence where k='optin_on')),true,'true persisted in private request row through public create');
select is((select notification_space from dashboard_private.ai_agent_requests where id=(select (v->>'id')::uuid from evidence where k='optin_on')),'space_1','space persisted in private request row through public create');
select is((select count(*) from dashboard_private.ai_agent_request_events where request_id=(select (v->>'id')::uuid from evidence where k='optin_on') and kind='created'),1::bigint,'true create records one immutable created audit');
update dashboard_private.chat_user_space_permissions set space_keys=array[]::text[] where user_id=pg_temp.ai_id(9);
set local role authenticated;
select throws_ok($q$select pg_temp.opt_create(902,'{"notifyOnDone":true,"notificationSpace":"space_1"}')$q$,'42501','ai_agent_space_forbidden','current own policy is rechecked before receipt replay');
reset role;
update dashboard_private.chat_user_space_permissions set space_keys=array['space_1','space_2','space_3'] where user_id=pg_temp.ai_id(9);
update dashboard_private.chat_space_configuration set configured=false,resource_name=null where space_key='space_1';
set local role authenticated;
select throws_ok($q$select pg_temp.opt_create(902,'{"notifyOnDone":true,"notificationSpace":"space_1"}')$q$,'42501','ai_agent_space_forbidden','current configuration is rechecked before receipt replay');
reset role;
update dashboard_private.chat_space_configuration set configured=true,resource_name='spaces/OPTIN_space_1' where space_key='space_1';
select set_config('request.jwt.claim.sub',pg_temp.ai_id(3)::text,true);
set local role authenticated;
select throws_ok($q$select pg_temp.opt_create(903,'{"notifyOnDone":true,"notificationSpace":"space_1"}')$q$,'42501','ai_agent_space_forbidden','another employee cannot borrow requester policy');
reset role;
select set_config('request.jwt.claim.sub',pg_temp.ai_id(1)::text,true);
set local role authenticated;
select is(pg_temp.opt_create(904,'{"notifyOnDone":true,"notificationSpace":"space_4"}')->>'notificationSpace','space_4','admin selects any configured catalog slot without employee permission row');
select throws_ok($q$select pg_temp.opt_create(905,'{"notifyOnDone":true,"notificationSpace":"space_3"}')$q$,'42501','ai_agent_space_forbidden','admin still cannot select an unconfigured slot');
reset role;
select set_config('request.jwt.claim.sub',pg_temp.ai_id(9)::text,true);
set local role authenticated;
select lives_ok($q$select pg_temp.opt_create(n) from generate_series(910,917)n$q$,'eight more creates fit same ten-request hourly budget');
select throws_ok($q$select pg_temp.opt_create(918,'{"notifyOnDone":true,"notificationSpace":"space_1"}')$q$,'54000','ai_agent_rate_limited','ON create shares existing atomic create budget');
select is(pg_temp.opt_create(902,'{"notifyOnDone":true,"notificationSpace":"space_1"}'),(select v from evidence where k='optin_on'),'ON replay consumes no hourly budget');
reset role;
update public.profiles set role='viewer' where id=pg_temp.ai_id(9);
set local role authenticated;
select throws_ok($q$select pg_temp.opt_create(902,'{"notifyOnDone":true,"notificationSpace":"space_1"}')$q$,'42501','ai_agent_forbidden','current actor role is checked before ON receipt replay');
reset role;
select is(jsonb_build_object('outbox',(select count(*) from dashboard_private.chat_delivery_outbox),'events',(select count(*) from dashboard_private.notification_events),'deliveries',(select count(*) from dashboard_private.notification_deliveries)),(select v from evidence where k='before_optin'),'create/replay/denial never send or create completion/legacy notification');

select * from finish();
rollback;
